async function p(e){return y(e)}async function u(e){return b(e)}async function f(e){return F(e)}async function d(e,n=null){const{parseGFF:s}=await import("./parseGFF-C2R_hNwd.js");return s(e,n)}async function g(e){return w(e)}async function m(e){return M(e)}async function h(e){return z(e)}async function k(e){return O(e)}function y(e){const n={};if(!e)return n;const s=e.split(/\r?\n/);if(s.length<2)return n;const i=s[0].split(/\t/);for(let a=1;a<s.length;++a){const t=s[a].trim();if(!t)continue;const c=t.split(/\t/),r={};for(let o=0;o<i.length;++o)r[i[o]]=c[o];r.gene_id&&(n[r.gene_id]=r)}return n}function b(e){const n={};if(!e)return n;const s=e.split(/\r?\n/);if(s.length<2)return n;const i=s[0].split(/\t/);for(let a=1;a<s.length;++a){const t=s[a].trim();if(!t)continue;const c=t.split(/\t/),r={};for(let l=0;l<i.length;++l)r[i[l]]=c[l];const o=c[0];o&&(n[o]=r)}return n}function F(e){const n=[];if(!e)return n;const s=e.split(/\r?\n/);if(s.length<2)return n;const i=s[0].split(/\t/);for(let a=1;a<s.length;++a){const t=s[a].trim();if(!t)continue;const c=t.split(/\t/),r={};for(let o=0;o<i.length;++o)r[i[o]]=c[o];n.push(r)}return n}function w(e){const n=[];if(!e)return n;const s=e.split(/\r?\n/);for(let i=0;i<s.length;++i){const a=s[i].trim();if(!a)continue;const t=a.split(/\s+/);n.push({geneA:t[0],geneB:t[1],score:parseFloat(t[2])||0})}return n}function M(e){const n=[];if(!e)return n;const s=e.split(/\r?\n/);for(let i=0;i<s.length;++i){const a=s[i].trim();if(!a)continue;const t=a.split(/\s+/);n.push({seqidA:t[0],startA:parseInt(t[1],10),endA:parseInt(t[2],10),seqidB:t[3],startB:parseInt(t[4],10),endB:parseInt(t[5],10),similarity:parseFloat(t[6])||0})}return n}function z(e){const n={};if(!e)return n;const s=e.split(/\r?\n/);for(let i=0;i<s.length;++i){const a=s[i].trim();if(!a)continue;const t=a.split(/\s+/),c=t[0],r={domainName:t[1],start:parseInt(t[2],10),end:parseInt(t[3],10),evalue:parseFloat(t[4])||0};n[c]||(n[c]=[]),n[c].push(r)}return n}function O(e){const n={};if(!e)return n;const s=e.split(/\r?\n/);for(let i=0;i<s.length;++i){const a=s[i].trim();if(!a)continue;const t=a.split(/\t/);t.length>=3&&(n[t[0]]={type:t[1],description:t[2]})}return n}self.addEventListener("message",async e=>{const{id:n,type:s,text:i,config:a}=e.data||{};try{let t=null;switch(s){case"gff":t=await d(i,a);break;case"proteinLinks":t=await g(i);break;case"nucleotideLinks":t=await m(i);break;case"domains":t=await h(i);break;case"baselines":t=await f(i);break;case"proteinMetadata":t=await p(i);break;case"treeMetadata":t=await u(i);break;case"nonCoding":t=await k(i);break;default:throw new Error("unknown parse type: "+String(s))}self.postMessage({id:n,result:t})}catch(t){self.postMessage({id:n,error:t&&t.message?t.message:String(t)})}});
